"""Native ("built-in") implementations of the standard nand2tetris chip set.

The official Hardware Simulator resolves a chip-part name by looking for
`<Name>.hdl` in the directory of the chip being loaded; when that file does
not exist it falls back to the built-in implementation.  This module supplies
those built-in implementations so the same resolution rule can be used here.

Conventions
-----------
* Pin values are plain Python ints holding an unsigned bit pattern.
* Combinational chips are described by ``COMBINATIONAL[name] = (ins, outs, fn)``
  where ``ins``/``outs`` are ``[(pin, width), ...]`` and ``fn`` maps a dict of
  input values to a dict of output values.
* Clocked chips are classes exposing ``combinational``, ``clock_up`` and
  ``clock_down`` (see ``SequentialChip``).
"""

W16 = 0xFFFF


def _mask(v, width):
    return v & ((1 << width) - 1)


def _bits16(v):
    return [(v >> i) & 1 for i in range(16)]


def _from_bits(bits):
    v = 0
    for i, b in enumerate(bits):
        if b:
            v |= 1 << i
    return v


# ---------------------------------------------------------------------------
# combinational built-ins
# ---------------------------------------------------------------------------

COMBINATIONAL = {}


def _comb(name, ins, outs):
    def deco(fn):
        COMBINATIONAL[name] = (ins, outs, fn)
        return fn
    return deco


@_comb('Nand', [('a', 1), ('b', 1)], [('out', 1)])
def _nand(v):
    return {'out': 1 - (v['a'] & v['b'])}


@_comb('Not', [('in', 1)], [('out', 1)])
def _not(v):
    return {'out': 1 - v['in']}


@_comb('And', [('a', 1), ('b', 1)], [('out', 1)])
def _and(v):
    return {'out': v['a'] & v['b']}


@_comb('Or', [('a', 1), ('b', 1)], [('out', 1)])
def _or(v):
    return {'out': v['a'] | v['b']}


@_comb('Xor', [('a', 1), ('b', 1)], [('out', 1)])
def _xor(v):
    return {'out': v['a'] ^ v['b']}


@_comb('Mux', [('a', 1), ('b', 1), ('sel', 1)], [('out', 1)])
def _mux(v):
    return {'out': v['b'] if v['sel'] else v['a']}


@_comb('DMux', [('in', 1), ('sel', 1)], [('a', 1), ('b', 1)])
def _dmux(v):
    return {'a': 0 if v['sel'] else v['in'], 'b': v['in'] if v['sel'] else 0}


@_comb('Not16', [('in', 16)], [('out', 16)])
def _not16(v):
    return {'out': (~v['in']) & W16}


@_comb('And16', [('a', 16), ('b', 16)], [('out', 16)])
def _and16(v):
    return {'out': v['a'] & v['b']}


@_comb('Or16', [('a', 16), ('b', 16)], [('out', 16)])
def _or16(v):
    return {'out': v['a'] | v['b']}


@_comb('Mux16', [('a', 16), ('b', 16), ('sel', 1)], [('out', 16)])
def _mux16(v):
    return {'out': v['b'] if v['sel'] else v['a']}


@_comb('Or8Way', [('in', 8)], [('out', 1)])
def _or8way(v):
    return {'out': 1 if v['in'] else 0}


@_comb('Mux4Way16',
       [('a', 16), ('b', 16), ('c', 16), ('d', 16), ('sel', 2)],
       [('out', 16)])
def _mux4way16(v):
    return {'out': [v['a'], v['b'], v['c'], v['d']][v['sel']]}


@_comb('Mux8Way16',
       [('a', 16), ('b', 16), ('c', 16), ('d', 16),
        ('e', 16), ('f', 16), ('g', 16), ('h', 16), ('sel', 3)],
       [('out', 16)])
def _mux8way16(v):
    return {'out': [v['a'], v['b'], v['c'], v['d'],
                    v['e'], v['f'], v['g'], v['h']][v['sel']]}


@_comb('DMux4Way', [('in', 1), ('sel', 2)],
       [('a', 1), ('b', 1), ('c', 1), ('d', 1)])
def _dmux4way(v):
    out = {'a': 0, 'b': 0, 'c': 0, 'd': 0}
    out['abcd'[v['sel']]] = v['in']
    return out


@_comb('DMux8Way', [('in', 1), ('sel', 3)],
       [('a', 1), ('b', 1), ('c', 1), ('d', 1),
        ('e', 1), ('f', 1), ('g', 1), ('h', 1)])
def _dmux8way(v):
    out = {k: 0 for k in 'abcdefgh'}
    out['abcdefgh'[v['sel']]] = v['in']
    return out


@_comb('HalfAdder', [('a', 1), ('b', 1)], [('sum', 1), ('carry', 1)])
def _halfadder(v):
    return {'sum': v['a'] ^ v['b'], 'carry': v['a'] & v['b']}


@_comb('FullAdder', [('a', 1), ('b', 1), ('c', 1)],
       [('sum', 1), ('carry', 1)])
def _fulladder(v):
    s = v['a'] + v['b'] + v['c']
    return {'sum': s & 1, 'carry': 1 if s > 1 else 0}


@_comb('Add16', [('a', 16), ('b', 16)], [('out', 16)])
def _add16(v):
    return {'out': (v['a'] + v['b']) & W16}


@_comb('Inc16', [('in', 16)], [('out', 16)])
def _inc16(v):
    return {'out': (v['in'] + 1) & W16}


@_comb('ALU',
       [('x', 16), ('y', 16), ('zx', 1), ('nx', 1),
        ('zy', 1), ('ny', 1), ('f', 1), ('no', 1)],
       [('out', 16), ('zr', 1), ('ng', 1)])
def _alu(v):
    x, y = v['x'], v['y']
    if v['zx']:
        x = 0
    if v['nx']:
        x = (~x) & W16
    if v['zy']:
        y = 0
    if v['ny']:
        y = (~y) & W16
    out = (x + y) & W16 if v['f'] else (x & y)
    if v['no']:
        out = (~out) & W16
    return {'out': out,
            'zr': 1 if out == 0 else 0,
            'ng': 1 if out & 0x8000 else 0}


# ---------------------------------------------------------------------------
# clocked built-ins
# ---------------------------------------------------------------------------

class SequentialChip:
    """Base class for clocked built-in chips.

    Timing follows the official simulator: ``clock_up`` (tick) latches the
    inputs without changing any output, ``clock_down`` (tock) commits the
    latched value so that it becomes visible on the outputs.
