    OUTS = []

    def combinational(self, v):
        raise NotImplementedError

    def clock_up(self, v):
        pass

    def clock_down(self):
        pass


SEQUENTIAL = {}


def _seq(name):
    def deco(cls):
        SEQUENTIAL[name] = cls
        cls.CHIP_NAME = name
        return cls
    return deco


