    return {'out': (v['in'] + 1) & W16}


@_comb('ALU',
       [('x', 16), ('y', 16), ('zx', 1), ('nx', 1),
        ('zy', 1), ('ny', 1), ('f', 1), ('no', 1)],
       [('out', 16), ('zr', 1), ('ng', 1)])
