            if wire in ('true', 'True'):
                return [CONST1] * span
            if wire in ('false', 'False'):
                return [CONST0] * span
            nodes = wires[wire]
            if wire_sl is None:
                sel = nodes[:span] if span <= len(nodes) else nodes
            else:
                sel = nodes[wire_sl[0]:wire_sl[1] + 1]
            if len(sel) != span:
                raise HDLError('%s: width mismatch on wire %s (%d vs %d)'
                               % (chip.name, wire, len(sel), span))
            return sel

        for part, in_w, out_w, sub in parts_meta:
            sub_in = {p: [CONST0] * w for p, w in in_w.items()}
            sub_out = {p: None for p in out_w}
            out_conns = {}
            for pin, pin_sl, wire, wire_sl in part.conns:
                if pin in in_w:
                    pw = in_w[pin]
                    lo, hi = (pin_sl if pin_sl else (0, pw - 1))
                    span = hi - lo + 1
                    src = wire_nodes(wire, wire_sl, span)
                    sub_in[pin] = sub_in[pin][:lo] + src + sub_in[pin][hi + 1:]
                elif pin in out_w:
                    pw = out_w[pin]
                    lo, hi = (pin_sl if pin_sl else (0, pw - 1))
                    span = hi - lo + 1
                    dst = wire_nodes(wire, wire_sl, span)
                    out_conns.setdefault(pin, []).append((lo, hi, dst))
                else:
                    raise HDLError('%s: chip %s has no pin %s'
                                   % (chip.name, part.chip, pin))

            for pin, w in out_w.items():
                nodes = [None] * w
                for lo, hi, dst in out_conns.get(pin, []):
                    for i, n in enumerate(dst):
                        nodes[lo + i] = n
                for i in range(w):
                    if nodes[i] is None:
                        nodes[i] = self.net.new_node()
                sub_out[pin] = nodes

            if sub is None:
                self.net.add_instance(part.chip, sub_in, sub_out)
            else:
                child_pins = dict(sub_in)
                child_pins.update(sub_out)
                self._expand(sub, child_pins)

