    def _propagate(self, queue):
        net = self.net
        values = net.values
        instances = net.instances
        readers = net.readers
        in_queue = bytearray(len(instances))
        dq = deque()
        for i in queue:
            if not in_queue[i]:
                in_queue[i] = 1
                dq.append(i)
        steps = 0
        while dq:
            steps += 1
            if steps > self.MAX_ITERATIONS:
                raise HDLError('combinational loop detected in %s'
                               % self.chip.name)
            idx = dq.popleft()
            in_queue[idx] = 0
            inst = instances[idx]
            vals = {}
            for pin, nodes in inst.ins.items():
                v = 0
                for i, n in enumerate(nodes):
                    if values[n]:
                        v |= 1 << i
                vals[pin] = v
            if inst.kind == 'comb':
                outs = inst.fn(vals)
            else:
                outs = inst.obj.combinational(vals)
            changed = []
            for pin, value in outs.items():
                net.write(inst.outs[pin], value, changed)
            for n in changed:
                for r in readers.get(n, ()):
                    if not in_queue[r]:
                        in_queue[r] = 1
                        dq.append(r)

    def eval_all(self):
        self._propagate(range(len(self.net.instances)))

    def eval(self):
        self.eval_all()

    def set_pin(self, name, value):
        if name not in self.pin_nodes:
            raise HDLError('no such pin: %s' % name)
        changed = []
        self.net.write(self.pin_nodes[name], value, changed)
        queue = []
        for n in changed:
            queue.extend(self.net.readers.get(n, ()))
        self._propagate(queue)

    def get_pin(self, name):
        return self.net.read(self.pin_nodes[name])

    def tick(self):
        self.eval_all()
