    # -- internal state access -------------------------------------------
    def find_chip(self, name):
        insts = self.net.by_chip.get(name)
        if not insts:
            raise HDLError('no built-in %s instance in %s'
                           % (name, self.chip.name))
        return insts[0].obj

    def get_internal(self, name, index):
        obj = self.find_chip(name)
        return obj.get_value(index)

    def set_internal(self, name, index, value):
        obj = self.find_chip(name)
        obj.set_value(value, index)
        self.eval_all()

